"""Unit tests for alarm manager, audio cooldowns, and acoustic safety caps."""

import pytest

from src.alarm import AlarmManager, MockAudioBackend, generate_sine_wave_wav
from src.fusion import SystemState


def test_generate_sine_wave_wav_validity() -> None:
    """Verifies that generated bytes contain a valid RIFF/WAVE header."""
    wav_bytes = generate_sine_wave_wav(frequency_hz=440, duration_sec=0.1, volume=0.5)
    assert len(wav_bytes) > 44  # Standard WAV header is 44 bytes
    assert wav_bytes[:4] == b"RIFF"
    assert wav_bytes[8:12] == b"WAVE"


def test_alarm_silent_in_alert_state() -> None:
    """Verifies that nominal ALERT state never triggers audio output."""
    backend = MockAudioBackend()
    mgr = AlarmManager(backend=backend)
    dispatched = mgr.update(SystemState.ALERT, timestamp=100.0)
    assert dispatched is False
    assert len(backend.play_history) == 0


def test_alarm_dispatches_with_volume_cap_and_frequency() -> None:
    """Verifies that DROWSY dispatches the configured frequency with volume cap."""
    backend = MockAudioBackend()
    mgr = AlarmManager(
        backend=backend,
        volume_cap=0.65,
        drowsy_frequency_hz=800,
    )
    dispatched = mgr.update(SystemState.DROWSY, timestamp=100.0)
    assert dispatched is True
    assert len(backend.play_history) == 1
    _, freq, _dur, vol = backend.play_history[0]
    assert freq == 800
    assert vol == pytest.approx(0.65, abs=1e-4)


def test_alarm_cooldown_suppression() -> None:
    """Verifies that rapid alarm requests within cooldown period (5.0s) are suppressed."""
    backend = MockAudioBackend()
    mgr = AlarmManager(backend=backend, alarm_cooldown_sec=5.0)

    # First alarm at t=100.0 -> Dispatched
    assert mgr.update(SystemState.DROWSY, timestamp=100.0) is True
    assert len(backend.play_history) == 1

    # Second alarm at t=103.0 (< 5s cooldown) -> Suppressed
    assert mgr.update(SystemState.DROWSY, timestamp=103.0) is False
    assert len(backend.play_history) == 1

    # Third alarm at t=105.5 (> 5s cooldown) -> Dispatched
    assert mgr.update(SystemState.DROWSY, timestamp=105.5) is True
    assert len(backend.play_history) == 2


def test_alarm_mute_toggle() -> None:
    """Verifies that muting silences alarms completely."""
    backend = MockAudioBackend()
    mgr = AlarmManager(backend=backend)

    mgr.toggle_mute()
    assert mgr.muted is True
    assert mgr.update(SystemState.DROWSY, timestamp=100.0) is False
    assert len(backend.play_history) == 0

    mgr.toggle_mute()
    assert mgr.muted is False
    assert mgr.update(SystemState.DROWSY, timestamp=100.0) is True
    assert len(backend.play_history) == 1


def test_alarm_max_continuous_safety_pause() -> None:
    """Verifies that continuous sounding past max_continuous_alarm_sec triggers pause."""
    backend = MockAudioBackend()
    mgr = AlarmManager(
        backend=backend,
        alarm_cooldown_sec=2.0,
        max_continuous_alarm_sec=5.0,
    )

    t = 100.0
    # Start alarm
    assert mgr.update(SystemState.DROWSY, timestamp=t) is True

    # Advance time within continuous limit
    t += 2.5
    assert mgr.update(SystemState.DROWSY, timestamp=t) is True

    # Advance time past 5.0s limit (continuous from 100.0 to 105.5 = 5.5s)
    t = 105.5
    # Should trigger safety silence pause
    assert mgr.update(SystemState.DROWSY, timestamp=t) is False

    # During safety pause (5.0s silence)
    t = 108.0
    assert mgr.update(SystemState.DROWSY, timestamp=t) is False

    # After safety pause (105.5 + 5.0 = 110.5)
    t = 111.0
    assert mgr.update(SystemState.DROWSY, timestamp=t) is True
